def count_primes(n):
    primes = []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(n**0.5) + 1):
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
    for p in range(2, n + 1):
        if is_prime[p]:
            primes.append(p)
    return len(primes)

def C(n):
    pi_n = count_primes(n)

    # C(n) = (Primes <= n, p!=7, 17) + [n>=14] + [n>=51]

    # Primes <= n, p!=7, 17:
    count_p_other = pi_n
    if n >= 7:
        count_p_other -= 1 # Exclude 7
    if n >= 17:
        count_p_other -= 1 # Exclude 17

    # Adjust for 7 and 17 being included/excluded based on exponents
    # 7 is included if n >= 14 (v7(n!) >= 2)
    if n >= 14:
        count_p_other += 1 

    # 17 is included if n >= 51 (v17(n!) >= 3)
    if n >= 51:
        count_p_other += 1

    return count_p_other

