import math

def prime_count(n):
    """Returns pi(n), the number of primes less than or equal to n."""
    if n < 2:
        return 0
    count = 0
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(math.sqrt(n)) + 1):
        if is_prime[p]:
            for multiple in range(p*p, n + 1, p):
                is_prime[multiple] = False
    for p in range(2, n + 1):
        if is_prime[p]:
            count += 1
    return count

def legendre(n, p):
    """Calculates the exponent of prime p in n!."""
    count = 0
    while n > 0:
        n //= p
        count += n
    return count

def omega(n):
    """
    Calculates omega(K) where K = n! / (7 * 17^2) for n >= 34.
    We calculate this using the number of distinct prime factors.
    """
    if n < 34:
        # K is not an integer, number of pairs is 0.
        return 0 

    # Primes up to n
    primes = []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(math.sqrt(n)) + 1):
        if is_prime[p]:
            for multiple in range(p*p, n + 1, p):
                is_prime[multiple] = False
    for p in range(2, n + 1):
        if is_prime[p]:
            primes.append(p)

    # N(n) = 2^omega(K). We check if omega(K) <= 11.

    omega_k = 0
    for p in primes:
        if p == 7:
            exp_7 = legendre(n, 7)
            if exp_7 >= 2:
                omega_k += 1 # 7 divides K
        elif p == 17:
            exp_17 = legendre(n, 17)
            if exp_17 >= 3:
                omega_k += 1 # 17 divides K
        else:
            # All other primes p <= n divide K
            omega_k += 1

    return omega_k

# Check for the transition points and solutions
solutions = []
max_omega = 11

# Test n up to 60 to ensure we pass the threshold
for n in range(1, 61):
    omega_n = omega(n)
    if omega_n <= max_omega:
        solutions.append(n)
    # Optimization: if we hit max_omega + 1, and the function is monotonic, we can stop.
    # Since omega increases monotonically (or stays the same), we can break early.
    elif n >= 34 and omega_n > max_omega and omega(n+1) > max_omega:
        # This relies on omega being non-decreasing, which it is.
        break

print(f"Solutions found (n): {solutions}")
print(f"Sum of solutions found: {sum(solutions)}")
